T['engineering'] = [
  `{ id: 'section-modulus', name: 'Section Modulus Calculator', desc: 'Elastic section modulus of a rectangle or circle', kw: 'section modulus calculator beam bending rectangle circle elastic design',
    inputs: [{id:'shape',label:'Shape',type:'select',opts:[{v:'rect',l:'Rectangle (b × h)'},{v:'circle',l:'Circle (diameter d)'}],def:'rect'},{id:'b',label:'Width b (mm)',type:'number',def:50},{id:'h',label:'Height h / Diameter d (mm)',type:'number',def:100}],
    calc: function(v){ if(v.h<=0||(v.shape==='rect'&&v.b<=0)) return{result:'Dimensions must be positive',chart:'',extra:''}; var S=v.shape==='circle'?Math.PI*Math.pow(v.h,3)/32:v.b*v.h*v.h/6; return{result:'Section Modulus: '+S.toLocaleString('en-US',{maximumFractionDigits:1})+' mm³',chart:Charts.gauge(v.h,200),extra:'Bending stress σ = M ÷ S | Rectangle: bh²/6; circle: πd³/32 — depth matters more than width (h² term)'};},
    steps: function(v){ var S=v.shape==='circle'?Math.PI*Math.pow(v.h,3)/32:v.b*v.h*v.h/6; return['Formula: '+(v.shape==='circle'?'S = πd³/32':'S = bh²/6'),'Step 1: '+(v.shape==='circle'?'d³ = '+v.h+'³ = '+Math.pow(v.h,3):'h² = '+v.h+'² = '+(v.h*v.h)),'Step 2: S = '+S.toLocaleString('en-US',{maximumFractionDigits:1})+' mm³','Use S to size beams: for a given moment M, bending stress falls as S grows'];} }`,
  `{ id: 'shaft-torsion', name: 'Shaft Torsion Stress Calculator', desc: 'Shear stress in a solid circular shaft under torque', kw: 'shaft torsion calculator shear stress solid circular torque polar moment',
    inputs: [{id:'T',label:'Torque T (N·m)',type:'number',def:100},{id:'d',label:'Shaft Diameter (mm)',type:'number',def:20}],
    calc: function(v){ if(v.d<=0) return{result:'Diameter must be positive',chart:'',extra:''}; var tau=16*v.T/(Math.PI*Math.pow(v.d/1000,3)); var J=Math.PI*Math.pow(v.d/1000,4)/32; return{result:'Shear Stress: '+(tau/1e6).toFixed(2)+' MPa',chart:Charts.gauge(tau/1e6,200),extra:'Polar moment J = πd⁴/32 = '+J.toExponential(3)+' m⁴ | τ = T·r/J gives the same value at the outer surface'};},
    steps: function(v){ var tau=16*v.T/(Math.PI*Math.pow(v.d/1000,3)); return['Formula: τmax = 16T ÷ (πd³)','Step 1: d = '+(v.d/1000)+' m → d³ = '+Math.pow(v.d/1000,3).toExponential(3)+' m³','Step 2: τ = 16 × '+v.T+' ÷ (π × '+Math.pow(v.d/1000,3).toExponential(3)+') = '+(tau/1e6).toFixed(2)+' MPa','Stress scales with 1/d³ — halving the diameter multiplies stress eightfold'];} }`,
  `{ id: 'pulley-speed', name: 'Pulley Speed Calculator', desc: 'Driven pulley rpm from the diameter ratio', kw: 'pulley speed calculator rpm diameter ratio belt drive driven sheave',
    inputs: [{id:'d1',label:'Driver Diameter (mm)',type:'number',def:100},{id:'n1',label:'Driver Speed (rpm)',type:'number',def:1750},{id:'d2',label:'Driven Diameter (mm)',type:'number',def:200}],
    calc: function(v){ if(v.d1<=0||v.d2<=0||v.n1<=0) return{result:'Diameters and driver speed must be positive',chart:'',extra:''}; var n2=v.d1*v.n1/v.d2; return{result:'Driven Speed: '+n2.toFixed(1)+' rpm',chart:Charts.gauge(n2,Math.max(v.n1,1)),extra:'Speed ratio: '+(v.d2/v.d1).toFixed(2)+':1 | Belt speed ≈ π × d₁ × n₁ = '+(Math.PI*v.d1/1000*v.n1).toFixed(0)+' m/min (same on both pulleys)'};},
    steps: function(v){ var n2=v.d1*v.n1/v.d2; return['Formula: n2 = (d1 × n1) ÷ d2 — belt speed is equal on both pulleys','Step 1: d1 × n1 = '+v.d1+' × '+v.n1+' = '+(v.d1*v.n1),'Step 2: ÷ d2 ('+v.d2+') = '+n2.toFixed(1)+' rpm','A larger driven pulley turns slower but delivers more torque — power (ignoring losses) stays the same'];} }`,
  `{ id: 'manning-flow', name: 'Manning Flow Calculator', desc: 'Full-pipe discharge via the Manning equation', kw: 'manning equation calculator pipe flow discharge slope roughness gravity main',
    inputs: [{id:'D',label:'Pipe Diameter (m)',type:'number',def:0.3},{id:'n',label:'Manning n (roughness)',type:'number',def:0.013},{id:'S',label:'Slope S (m/m)',type:'number',def:0.01}],
    calc: function(v){ if(v.D<=0||v.n<=0||v.S<=0) return{result:'Diameter, n and slope must be positive',chart:'',extra:''}; var A=Math.PI*v.D*v.D/4; var R=v.D/4; var Q=A*Math.pow(R,2/3)*Math.sqrt(v.S)/v.n; return{result:'Discharge: '+Q.toFixed(4)+' m³/s',chart:Charts.gauge(Q,1),extra:'Area: '+A.toFixed(5)+' m² | Hydraulic radius: '+R.toFixed(4)+' m | Velocity: '+(Q/A).toFixed(3)+' m/s | ≈ '+(Q*15850.32).toFixed(0)+' gpm'};},
    steps: function(v){ var A=Math.PI*v.D*v.D/4; var R=v.D/4; var Q=A*Math.pow(R,2/3)*Math.sqrt(v.S)/v.n; return['Formula: Q = (1/n) × A × R^(2/3) × √S','Step 1: A = πD²/4 = '+A.toFixed(5)+' m²; full-pipe R = D/4 = '+R.toFixed(4)+' m','Step 2: R^(2/3) = '+Math.pow(R,2/3).toFixed(4)+'; √S = '+Math.sqrt(v.S).toFixed(4),'Step 3: Q = '+(1/v.n).toFixed(2)+' × '+A.toFixed(5)+' × '+Math.pow(R,2/3).toFixed(4)+' × '+Math.sqrt(v.S).toFixed(4)+' = '+Q.toFixed(4)+' m³/s'];} }`,
  `{ id: 'orifice-flow', name: 'Orifice Flow Calculator', desc: 'Discharge through a sharp-edged orifice', kw: 'orifice flow calculator discharge coefficient tank drainage torricelli head',
    inputs: [{id:'cd',label:'Discharge Coefficient Cd',type:'number',def:0.62},{id:'d',label:'Orifice Diameter (m)',type:'number',def:0.05},{id:'h',label:'Head Above Orifice (m)',type:'number',def:2}],
    calc: function(v){ if(v.cd<=0||v.d<=0||v.h<0) return{result:'Cd and diameter must be positive; head at least 0',chart:'',extra:''}; var A=Math.PI*v.d*v.d/4; var Q=v.cd*A*Math.sqrt(2*9.81*v.h); return{result:'Flow: '+(Q*1000).toFixed(2)+' L/s',chart:Charts.gauge(Q,0.05),extra:'Area: '+(A*1e4).toFixed(2)+' cm² | Jet velocity: '+Math.sqrt(2*9.81*v.h).toFixed(2)+' m/s (Torricelli) | Sharp edge Cd ≈ 0.61–0.63'};},
    steps: function(v){ var A=Math.PI*v.d*v.d/4; var Q=v.cd*A*Math.sqrt(2*9.81*v.h); return['Formula: Q = Cd × A × √(2gh)','Step 1: A = πd²/4 = '+(A*1e4).toFixed(2)+' cm²','Step 2: √(2 × 9.81 × '+v.h+') = '+Math.sqrt(2*9.81*v.h).toFixed(3)+' m/s','Step 3: Q = '+v.cd+' × '+A.toExponential(3)+' × '+Math.sqrt(2*9.81*v.h).toFixed(3)+' = '+(Q*1000).toFixed(2)+' L/s'];} }`,
  `{ id: 'three-phase-power', name: 'Three Phase Power Calculator', desc: 'Real power of a balanced three-phase load', kw: 'three phase power calculator kw voltage current power factor apparent reactive',
    inputs: [{id:'V',label:'Line Voltage (V)',type:'number',def:400},{id:'I',label:'Line Current (A)',type:'number',def:20},{id:'pf',label:'Power Factor (0–1)',type:'number',def:0.85}],
    calc: function(v){ if(v.V<=0||v.I<=0||v.pf<=0||v.pf>1) return{result:'Voltage and current positive; power factor between 0 and 1',chart:'',extra:''}; var P=Math.sqrt(3)*v.V*v.I*v.pf; var S=Math.sqrt(3)*v.V*v.I; return{result:'Real Power: '+(P/1000).toFixed(2)+' kW',chart:Charts.gauge(v.pf,1),extra:'Apparent power: '+(S/1000).toFixed(2)+' kVA | Reactive: '+(Math.sqrt(Math.max(0,S*S-P*P))/1000).toFixed(2)+' kVAR | Improving pf toward 1 cuts current for the same kW'};},
    steps: function(v){ var P=Math.sqrt(3)*v.V*v.I*v.pf; return['Formula: P = √3 × V × I × pf','Step 1: √3 × '+v.V+' × '+v.I+' = '+(Math.sqrt(3)*v.V*v.I).toFixed(0)+' VA (apparent)','Step 2: × pf '+v.pf+' = '+P.toFixed(0)+' W = '+(P/1000).toFixed(2)+' kW','Balanced-load assumption — unbalanced phases need per-phase calculation'];} }`,
  `{ id: 'ups-sizing', name: 'UPS Battery Sizing Calculator', desc: 'Battery amp-hours for a load and runtime target', kw: 'ups battery sizing calculator ah runtime backup load inverter efficiency',
    inputs: [{id:'load',label:'Load (W)',type:'number',def:600},{id:'min',label:'Backup Time (minutes)',type:'number',def:30},{id:'V',label:'Battery Bank Voltage (V)',type:'number',def:12},{id:'eff',label:'Inverter Efficiency (%)',type:'number',def:85}],
    calc: function(v){ if(v.load<=0||v.min<=0||v.V<=0||v.eff<=0||v.eff>100) return{result:'Load, time and voltage must be positive; efficiency 0–100%',chart:'',extra:''}; var ah=v.load*(v.min/60)/(v.V*v.eff/100); return{result:'Battery Capacity: '+ah.toFixed(1)+' Ah',chart:Charts.gauge(ah,200),extra:'Energy needed: '+(v.load*v.min/60/1000).toFixed(2)+' kWh | Add about 25% margin for aging and cold → '+(ah*1.25).toFixed(1)+' Ah'};},
    steps: function(v){ var ah=v.load*(v.min/60)/(v.V*v.eff/100); return['Formula: Ah = (load × hours) ÷ (V × efficiency)','Step 1: Energy = '+v.load+' W × '+(v.min/60).toFixed(2)+' h = '+(v.load*v.min/60).toFixed(0)+' Wh','Step 2: Delivered from batteries = Wh ÷ '+v.V+' V ÷ '+(v.eff/100)+' = '+ah.toFixed(1)+' Ah','Lead-acid rated at the 20-hour rate delivers less at high draw — check the discharge curve for short runtimes'];} }`,
];

T['everyday'] = [
  `{ id: 'poker-flush', name: 'Poker Flush Odds Calculator', desc: 'Probability of flush-type hands in 5-card poker', kw: 'poker flush odds calculator 5 card probability combinations straight flush',
    inputs: [{id:'matches',label:'Cards of the Same Suit Needed (1–5 of 5)',type:'number',def:5}],
    calc: function(v){ function C(n,k){ if(k<0||k>n) return 0; k=Math.min(k,n-k); var r=1; for(var i=1;i<=k;i++) r=r*(n-k+i)/i; return r; } var need=Math.min(5,Math.max(1,Math.round(v.matches))); var ways=C(4,1)*C(13,need)*C(39,5-need); var total=C(52,5); var p=ways/total; return{result:'Probability: '+(p*100).toFixed(4)+'%',chart:Charts.bar([p*100,100-p*100],['This hand','Other hands']),extra:'1 in '+Math.round(1/p).toLocaleString()+' hands | Ways: '+ways.toLocaleString()+' of '+total.toLocaleString()+' | A 5-card flush includes straight flushes — subtract 40 ways to exclude them'};},
    steps: function(v){ function C(n,k){ if(k<0||k>n) return 0; k=Math.min(k,n-k); var r=1; for(var i=1;i<=k;i++) r=r*(n-k+i)/i; return r; } var need=Math.min(5,Math.max(1,Math.round(v.matches))); var ways=C(4,1)*C(13,need)*C(39,5-need); var total=C(52,5); return['Formula: P = (suit choices × suit-card picks × other-suit fill) ÷ C(52,5)','Step 1: Ways = C(4,1) × C(13,'+need+') × C(39,'+(5-need)+') = '+ways.toLocaleString(),'Step 2: Total 5-card hands = C(52,5) = '+total.toLocaleString(),'Step 3: P = '+(ways/total*100).toFixed(4)+'% ≈ 1 in '+Math.round(total/ways).toLocaleString()];} }`,
  `{ id: 'easter-date', name: 'Easter Date Calculator', desc: 'Western Easter Sunday from the Gregorian computus', kw: 'easter date calculator computus good friday western sunday ash wednesday',
    inputs: [{id:'year',label:'Year (1583–4099)',type:'number',def:2026}],
    calc: function(v){ var y=Math.floor(v.year); if(y<1583||y>4099) return{result:'Enter a year between 1583 and 4099 (Gregorian era)',chart:'',extra:''}; var a=y%19, b=Math.floor(y/100), c=y%100, d=Math.floor(b/4), e=b%4, f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3), h=(19*a+b-d-g+15)%30, i=Math.floor(c/4), k=c%4, l=(32+2*e+2*i-h-k)%7, m=Math.floor((a+11*h+22*l)/451), mo=Math.floor((h+l-7*m+114)/31), day=((h+l-7*m+114)%31)+1; var names=['','January','February','March','April','May','June']; return{result:'Easter '+y+': '+names[mo]+' '+day,chart:Charts.bar([mo,12],['Month #','Months in year']),extra:'Good Friday is two days earlier; Ash Wednesday 46 days before | Orthodox Easter can differ — this is the Western date'};},
    steps: function(v){ var y=Math.floor(v.year); var a=y%19, b=Math.floor(y/100), c=y%100, d=Math.floor(b/4), e=b%4, f=Math.floor((b+8)/25), g=Math.floor((b-f+1)/3), h=(19*a+b-d-g+15)%30, i=Math.floor(c/4), k=c%4, l=(32+2*e+2*i-h-k)%7, m=Math.floor((a+11*h+22*l)/451), mo=Math.floor((h+l-7*m+114)/31), day=((h+l-7*m+114)%31)+1; var names=['','January','February','March','April','May','June']; return['Anonymous Gregorian computus (1583 onward)','Step 1: Golden number a = '+a+'; epact term h = '+h,'Step 2: Weekday offset l = '+l+'; correction m = '+m,'Step 3: Easter '+y+' = '+names[mo]+' '+day];} }`,
  `{ id: 'day-of-week', name: 'Day of Week Calculator', desc: 'Weekday for any calendar date', kw: 'day of week calculator what day was date weekday calendar finder',
    inputs: [{id:'date',label:'Date (YYYY-MM-DD)',type:'text',def:'2000-01-01'}],
    calc: function(v){ var d=new Date(v.date+'T12:00:00Z'); if(isNaN(d.getTime())) return{result:'Enter a valid date as YYYY-MM-DD',chart:'',extra:''}; var names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']; var start=new Date(Date.UTC(d.getUTCFullYear(),0,1)); var doy=Math.floor((d-start)/86400000)+1; return{result:names[d.getUTCDay()],chart:Charts.bar([doy,365],['Day of year','Days in year']),extra:v.date+' is day '+doy+' of '+d.getUTCFullYear()+' | Uses the proleptic Gregorian calendar for past centuries'};},
    steps: function(v){ var d=new Date(v.date+'T12:00:00Z'); var names=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']; return['Step 1: Parse '+v.date+' as a UTC date','Step 2: Weekday index = '+d.getUTCDay(),'Step 3: '+(isNaN(d.getTime())?'invalid date':names[d.getUTCDay()]),'ISO 8601 weeks start on Monday; Sunday-based calendars differ on week numbering'];} }`,
  `{ id: 'moon-phase', name: 'Moon Phase Calculator', desc: 'Lunar phase for a given date', kw: 'moon phase calculator lunar cycle synodic month full moon new moon illumination',
    inputs: [{id:'date',label:'Date (YYYY-MM-DD)',type:'text',def:'2000-01-06'}],
    calc: function(v){ var d=new Date(v.date+'T18:14:00Z'); if(isNaN(d.getTime())) return{result:'Enter a valid date as YYYY-MM-DD',chart:'',extra:''}; var ref=Date.UTC(2000,0,6,18,14); var age=((d.getTime()-ref)/86400000)%29.530588; if(age<0) age+=29.530588; var bands=[[1.85,'New Moon'],[5.54,'Waxing Crescent'],[9.23,'First Quarter'],[12.92,'Waxing Gibbous'],[16.61,'Full Moon'],[20.30,'Waning Gibbous'],[23.99,'Last Quarter'],[26.69,'Waning Crescent'],[99,'New Moon']]; var phase='New Moon'; for(var i=0;i<bands.length;i++){ if(age<bands[i][0]){ phase=bands[i][1]; break; } } var illum=(1-Math.cos(2*Math.PI*age/29.530588))/2*100; return{result:phase,chart:Charts.gauge(illum,100),extra:'Lunar age: '+age.toFixed(2)+' days into the 29.53-day synodic month | Illumination: '+illum.toFixed(1)+'% (approximate ±1 day)'};},
    steps: function(v){ var d=new Date(v.date+'T18:14:00Z'); var ref=Date.UTC(2000,0,6,18,14); var age=((d.getTime()-ref)/86400000)%29.530588; if(age<0) age+=29.530588; return['Method: count days since a known new moon (2000-01-06 18:14 UTC), then take the remainder over the 29.53-day synodic month','Step 1: Age = '+age.toFixed(2)+' days','Step 2: Match to the 8-phase cycle (new → first quarter → full → last quarter)','Approximation drifts about a day over decades — almanac values are authoritative for observation'];} }`,
  `{ id: 'meeting-cost', name: 'Meeting Cost Calculator', desc: 'Salary cost of a meeting in money and person-hours', kw: 'meeting cost calculator attendees hourly rate salary time waste productivity',
    inputs: [{id:'people',label:'Attendees',type:'number',def:8},{id:'rate',label:'Average Loaded Hourly Cost ($)',type:'number',def:50},{id:'hours',label:'Duration (hours)',type:'number',def:1.5}],
    calc: function(v){ if(v.people<=0||v.rate<=0||v.hours<=0) return{result:'Attendees, rate and duration must be positive',chart:'',extra:''}; var cost=v.people*v.rate*v.hours; var manHrs=v.people*v.hours; return{result:'Meeting Cost: $'+cost.toFixed(2),chart:Charts.bar([manHrs,cost],['Person-hours','Dollars']),extra:manHrs.toFixed(1)+' person-hours consumed | If held weekly: $'+(cost*52).toLocaleString('en-US',{maximumFractionDigits:0})+'/year — use loaded rates (salary + benefits) for honesty'};},
    steps: function(v){ var cost=v.people*v.rate*v.hours; return['Formula: cost = attendees × hourly cost × hours','Step 1: '+v.people+' × $'+v.rate+' × '+v.hours+' h = $'+cost.toFixed(2),'Step 2: Person-hours = '+v.people+' × '+v.hours+' = '+(v.people*v.hours).toFixed(1),'Step 3: Weekly cadence would cost $'+(cost*52).toLocaleString('en-US',{maximumFractionDigits:0})+' per year'];} }`,
];

T['utilities'] = [
  `{ id: 'password-entropy', name: 'Password Entropy Calculator', desc: 'Strength in bits from length and character pool', kw: 'password entropy calculator bits strength character pool brute force crack time',
    inputs: [{id:'len',label:'Password Length',type:'number',def:12},{id:'pool',label:'Character Pool Size (26 lower, 52 mixed case, 62 alphanumeric, 95 all ASCII)',type:'number',def:62}],
    calc: function(v){ if(v.len<=0||v.pool<=1) return{result:'Length must be positive; pool needs at least 2 characters',chart:'',extra:''}; var bits=v.len*Math.log2(v.pool); var secs=Math.pow(2,bits-1)/1e12; function fmt(s){ if(s<60) return s.toFixed(1)+' seconds'; if(s<3600) return (s/60).toFixed(1)+' minutes'; if(s<86400) return (s/3600).toFixed(1)+' hours'; if(s<3.15e7) return (s/86400).toFixed(1)+' days'; var y=s/3.15e7; return y>1e12?y.toExponential(1)+' years':y.toLocaleString('en-US',{maximumFractionDigits:0})+' years'; } var verdict=bits>=100?'excellent':bits>=75?'strong':bits>=60?'reasonable':bits>=40?'weak':'very weak'; return{result:'Entropy: '+bits.toFixed(1)+' bits',chart:Charts.gauge(bits,128),extra:'Pool^length = '+v.pool+'^'+v.len+' | Median crack time at 10¹² guesses/s: '+fmt(secs)+' — '+verdict+' | Assumes truly random characters; patterns lower real entropy'};},
    steps: function(v){ var bits=v.len*Math.log2(v.pool); return['Formula: entropy = length × log₂(pool size)','Step 1: log₂('+v.pool+') = '+Math.log2(v.pool).toFixed(4),'Step 2: bits = '+v.len+' × '+Math.log2(v.pool).toFixed(4)+' = '+bits.toFixed(1),'Each extra character multiplies search space by the pool size — length beats complexity'];} }`,
  `{ id: 'speech-time', name: 'Speech Time Calculator', desc: 'Speaking duration from word count and pace', kw: 'speech time calculator words per minute presentation duration pace toastmasters',
    inputs: [{id:'words',label:'Word Count',type:'number',def:650},{id:'wpm',label:'Speaking Pace (words per minute)',type:'number',def:130}],
    calc: function(v){ if(v.words<=0||v.wpm<=0) return{result:'Word count and pace must be positive',chart:'',extra:''}; var min=v.words/v.wpm; var mm=Math.floor(min); var ss=Math.round((min-mm)*60); if(ss===60){mm++;ss=0;} return{result:mm+' min '+ss+' s',chart:Charts.bar([min,mm],['Exact minutes','Rounded']),extra:'Conversational pace is 120–150 wpm; allow 1 slide per minute | Script pages (250 w/page): '+(v.words/250).toFixed(2)+' — rehearse aloud, reading pace differs'};},
    steps: function(v){ var min=v.words/v.wpm; var mm=Math.floor(min); var ss=Math.round((min-mm)*60); if(ss===60){mm++;ss=0;} return['Formula: minutes = words ÷ pace','Step 1: '+v.words+' ÷ '+v.wpm+' wpm = '+min.toFixed(2)+' minutes','Step 2: = '+mm+' min '+ss+' s','Add 10–15% for pauses, laughter, and slide transitions'];} }`,
];

