// ---------- insertion logic ----------
const check = process.argv.includes('--check');
const doQa = process.argv.includes('--qa');
let applied = 0, skipped = 0;

for (const file of Object.keys(T)) {
  const fp = path.join(ROOT, 'js', 'data', file + '.js');
  let src = fs.readFileSync(fp, 'utf8');
  const newIds = T[file].map(code => code.match(/\{ id: '([^']+)'/)[1]);
  const present = newIds.filter(id => src.includes("id: '" + id + "'"));
  if (present.length === newIds.length) { console.log('[skip] ' + file + ': all ' + newIds.length + ' already present'); skipped++; continue; }
  if (present.length) { console.error('[ABORT] ' + file + ' partially contains: ' + present.join(', ')); process.exit(1); }
  const block = T[file].map(code => '  ' + code).join(',\r\n\r\n');
  const anchor = src.lastIndexOf('\r\n];');
  if (anchor < 0) { console.error('[ABORT] no CRLF ]; tail in ' + file); process.exit(1); }
  const out = src.slice(0, anchor) + ',\r\n\r\n' + block + src.slice(anchor);
  if (!check) fs.writeFileSync(fp, out);
  applied += newIds.length;
  console.log('[ok] ' + file + ': +' + newIds.length + ' tools (' + newIds.join(', ') + ')');
}

if (doQa) {
  const tfp = path.join(ROOT, 'tests', 'unit', 'formula-qa-full.test.js');
  let tsrc = fs.readFileSync(tfp, 'utf8');
  const firstRow = "['finance', 'prorated-rent'";
  if (tsrc.includes(firstRow)) {
    console.log('[skip] QA rows already present');
  } else {
    const start = tsrc.indexOf('const CASES = [');
    if (start < 0) { console.error('[ABORT] CASES array not found'); process.exit(1); }
    const close = tsrc.indexOf('\n];', start);
    if (close < 0) { console.error('[ABORT] CASES terminator not found'); process.exit(1); }
    tsrc = tsrc.slice(0, close) + '\n' + QA_ROWS.join('\n') + tsrc.slice(close);
    if (!check) fs.writeFileSync(tfp, tsrc);
    console.log('[ok] +' + QA_ROWS.length + ' QA rows');
  }
}

console.log((check ? '[DRY RUN] would insert ' : 'Inserted ') + applied + ' tools across ' + Object.keys(T).length + ' files');
